package quality

import (
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"time"
)

// skipDirs are never scanned: dependencies, build output and test reports.
var skipDirs = map[string]bool{
	".git": true, "node_modules": true, "vendor": true, "dist": true, "build": true,
	"target": true, ".venv": true, "venv": true, "__pycache__": true, ".next": true,
	".nuxt": true, "coverage": true, ".idea": true, ".vscode": true, "bin": true, "obj": true,
	"test-results": true, "playwright-report": true, ".pytest_cache": true, ".turbo": true,
	// Generated by FazTudo itself: the code graph and the cleanup decision logs.
	"graphify-out": true, "faztudo-out": true,
}

const (
	maxWalkFiles = 20_000
	maxReadBytes = 2 << 20
)

// walk calls fn with the slash-separated relative path of every regular file
// outside skipDirs, up to maxWalkFiles.
func walk(root string, fn func(rel string, info fs.FileInfo)) {
	n := 0
	_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if path != root && skipDirs[d.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		if !d.Type().IsRegular() {
			return nil
		}
		if n++; n > maxWalkFiles {
			return filepath.SkipAll
		}
		info, err := d.Info()
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		fn(filepath.ToSlash(rel), info)
		return nil
	})
}

// CodeFiles lists, sorted, the repository's code files outside dependencies,
// build output and generated directories.
func CodeFiles(root string) []string {
	var out []string
	walk(root, func(rel string, _ fs.FileInfo) {
		if codeExts[ext(rel)] {
			out = append(out, rel)
		}
	})
	slices.Sort(out)
	return out
}

// FileClock is "now" as the file system stamps it. Compare file times
// against it, never against time.Now: Linux stamps files from a clock that
// ticks every few milliseconds and HFS+ or FAT round to seconds, so a file
// written right after time.Now() may carry an earlier time. The probe goes
// in dir's .git when there is one, out of the working tree, else in the
// system temporary directory; on failure it falls back to time.Now.
func FileClock(dir string) time.Time {
	probeDir := filepath.Join(dir, ".git")
	if st, err := os.Stat(probeDir); err != nil || !st.IsDir() {
		probeDir = os.TempDir()
	}
	f, err := os.CreateTemp(probeDir, "faztudo-clock-*")
	if err != nil {
		return time.Now()
	}
	name := f.Name()
	f.Close()
	defer os.Remove(name)
	st, err := os.Stat(name)
	if err != nil {
		return time.Now()
	}
	return st.ModTime()
}

// ChangedSince lists files modified at or after t, sorted.
func ChangedSince(root string, t time.Time) []string {
	var out []string
	walk(root, func(rel string, info fs.FileInfo) {
		if !info.ModTime().Before(t) {
			out = append(out, rel)
		}
	})
	slices.Sort(out)
	return out
}

func readFile(root, rel string) (string, bool) {
	info, err := os.Stat(filepath.Join(root, rel))
	if err != nil || info.Size() > maxReadBytes {
		return "", false
	}
	data, err := os.ReadFile(filepath.Join(root, rel))
	if err != nil {
		return "", false
	}
	return string(data), true
}

func ext(rel string) string { return strings.ToLower(filepath.Ext(rel)) }
